prompt:
You are the Tester agent. The Developer produced these files for
task TASK-001 (Create a basic landing page structure):

--- index.html ---
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; padding: 0; }
        .header, .footer { background-color: #004080; color: white; text-align: center; padding: 10px 0; }
        .content { margin: 20px; }
        form { max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #ccc; border-radius: 5px; }
        label { display: block; margin: 10px 0 5px; }
        input[type="text"], input[type="date"], select, textarea { width: 100%; padding: 8px; margin-bottom: 10px; box-sizing: border-box; }
        button { padding: 10px 20px; background-color: #004080; color: white; border: none; cursor: pointer; }
        #confirmation { display: none; text-align: center; margin-top: 20px; }
        .footer-note { font-size: 0.8em; color: #666; text-align: center; margin-top: 40px; }
    </style>
</head>
<body>
    <div class="header">
        <h1>MapleSure Insurance</h1>
    </div>
    <div class="content">
        <form id="claim-form">
            <label for="policy-number">Policy Number</label>
            <input type="text" id="policy-number" name="policy-number" />

            <label for="member-id">Member ID</label>
            <input type="text" id="member-id" name="member-id" />

            <button type="button" onclick="lookupMember()">Look up member</button>

            <div id="member-details"></div>

            <label for="last-day-worked">Last Day Worked</label>
            <input type="date" id="last-day-worked" name="last-day-worked" />

            <label for="first-day-absent">First Day Absent</label>
            <input type="date" id="first-day-absent" name="first-day-absent" />

            <label for="nature-of-absence">Nature of Absence</label>
            <select id="nature-of-absence" name="nature-of-absence">
                <option value="">Select...</option>
                <option value="illness">Illness</option>
                <option value="injury">Injury</option>
                <option value="other">Other</option>
            </select>

            <label for="details">Details</label>
            <textarea id="details" name="details" rows="4"></textarea>

            <label for="documents">Upload Documents</label>
            <input type="file" id="documents" name="documents" multiple onchange="updateFileList()" />
            <ul id="file-list"></ul>

            <button type="submit" onclick="submitClaim(event)">Submit Claim</button>
        </form>

        <div id="confirmation">
            <h2>Claim Submission</h2>
            <p>Reference Number: <span id="reference-number"></span></p>
            <p>Status: Received</p>
        </div>

        <div class="footer-note">
            <p>MapleSure Insurance — fictional demo application</p>
        </div>
    </div>
    <div class="footer">
        <p>&copy; 2023 MapleSure Insurance</p>
    </div>

    <script>
        const mockData = {
            "12345": { memberName: "John Doe", policyDetails: "Plan A" },
            "67890": { memberName: "Jane Smith", policyDetails: "Plan B" }
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetailsDiv = document.getElementById('member-details');
            const memberData = mockData[memberId];

            if (memberData) {
                memberDetailsDiv.innerHTML = `<p>Member Name: ${memberData.memberName}</p><p>Policy Details: ${memberData.policyDetails}</p>`;
            } else {
                memberDetailsDiv.innerHTML = '<p>Member not found.</p>';
            }
        }

        function updateFileList() {
            const input = document.getElementById('documents');
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';

            Array.from(input.files).forEach(file => {
                const li = document.createElement('li');
                li.textContent = file.name;
                fileList.appendChild(li);
            });
        }

        function submitClaim(event) {
            event.preventDefault();

            const referenceNumber = `MS-2026-08-${Math.floor(1000 + Math.random() * 9000)}`;
            document.getElementById('reference-number').textContent = referenceNumber;

            document.getElementById('claim-form').style.display = 'none';
            document.getElementById('confirmation').style.display = 'block';
        }
    </script>
</body>
</html>

Acceptance criteria:
- US-1-AC1: Given an anonymous or authenticated advisor, when navigating to '/', then the page shows the MapleSure branded header and footer.
- US-1-AC2: Given an anonymous or authenticated advisor, when navigating to '/', then the page structure is present with placeholder text and elements.

Write pytest tests (a single test_app.py) that verify the happy path
STRUCTURALLY against the actual file above — read index.html from
Path(__file__).parent and assert what the criteria need: the form and its
required field ids exist, the upload input allows multiple files, the
confirmation panel and status markup exist, the member lookup mock data is
present. 4 to 6 focused tests, stdlib + pytest only, no browser, no server,
no network. Every assertion must hold for the file exactly as shown above,
and must be independent of the current date, time, or environment — never
hard-code a year, month, or timestamp; where the page generates a value at
runtime, assert the generating code exists, not the value it would produce
today.

JSON schema: {"files": [{"path": "test_app.py", "content": str}]}
